-- =====================================================================
-- Agie's Resort - 100 FICTIONAL demonstration customers
-- Every name, email and phone number here is invented.
--   * emails use example.com (reserved, RFC 2606) - nothing is ever delivered
--   * phones use the synthetic block 0999-000-0xxx
--   * every row has is_demo = 1 and a [DEMO] note
-- Each customer also gets one past, completed, fully paid stay (DEMO-H001..H100),
-- because a customer may only exist through a reservation.
-- Idempotent: keyed on the unique email column. Re-importing updates
-- nothing and inserts no duplicates (ON DUPLICATE KEY UPDATE is a no-op).
-- Import AFTER agies_resort_db.sql (or after migrate_existing_db.sql).
-- Generated by database/tools/generate_seeds.py
-- =====================================================================
USE `agies_resort_db`;
SET NAMES utf8mb4;
START TRANSACTION;
ON DUPLICATE KEY UPDATE `customer_id` = `customer_id`;
-- One completed stay per customer (keeps every customer linked to a booking)
SELECT 'DEMO-H001', c.customer_id, 1, 1, 'Area 1 - Daytime', 'DAYTIME', (CURDATE() + INTERVAL -76 DAY), '08:00:00', '17:00:00', TIMESTAMP((CURDATE() + INTERVAL -76 DAY), '08:00:00'), TIMESTAMP((CURDATE() + INTERVAL -76 DAY), '17:00:00'), 17, 4000.00, 0, 0.00, 4000.00, 1000.00, 4000.00, 'PAID', 'COMPLETED', c.full_name, c.contact_number, '[DEMO] Past stay', TIMESTAMP((CURDATE() + INTERVAL -76 DAY) - INTERVAL 15 DAY, '10:05:00'), TIMESTAMP((CURDATE() + INTERVAL -76 DAY), '17:00:00'), 'WEBSITE', 1, TIMESTAMP((CURDATE() + INTERVAL -76 DAY) - INTERVAL 20 DAY, '09:00:00')
FROM `customers` c WHERE c.email = 'erlinda.navarro.demo001@example.com' AND NOT EXISTS (SELECT 1 FROM `reservations` WHERE `reservation_code` = 'DEMO-H001');
SET @rid = IF(ROW_COUNT() > 0, LAST_INSERT_ID(), NULL);
