INSERT INTO `reservations` (`reservation_code`,`customer_id`,`area_id`,`package_id`,`package_name`,`booking_type`,`booking_date`,`start_time`,`end_time`,`start_at`,`end_at`,`num_guests`,`base_rate`,`extra_guests`,`additional_fee`,`total_amount`,`down_payment`,`amount_paid`,`payment_status`,`status`,`guest_name`,`guest_contact`,`notes`,`confirmed_at`,`completed_at`,`source`,`is_demo`,`created_at`)
INSERT INTO `reservation_status_history` (`reservation_id`,`old_status`,`new_status`,`changed_by`,`remarks`) SELECT @rid, NULL, 'PENDING', NULL, '[DEMO] Reservation submitted from website' FROM DUAL WHERE @rid IS NOT NULL;
INSERT INTO `reservation_status_history` (`reservation_id`,`old_status`,`new_status`,`changed_by`,`remarks`) SELECT @rid, 'PENDING', 'CONFIRMED', NULL, '[DEMO] Down payment verified; reservation confirmed' FROM DUAL WHERE @rid IS NOT NULL;
INSERT INTO `reservation_status_history` (`reservation_id`,`old_status`,`new_status`,`changed_by`,`remarks`) SELECT @rid, 'CONFIRMED', 'COMPLETED', NULL, '[DEMO] Stay completed' FROM DUAL WHERE @rid IS NOT NULL;
